import unittest, datetime, validator_v2.qualification_validator as qv
class TestPciParsing(unittest.TestCase):
    def test_standard_pci_not_malformed(self):
        now = datetime.datetime.now(datetime.timezone.utc)
        dev = {'pci_id': '0000:01:00.0', 'vendor': 'NVIDIA', 'memory': {'total_bytes': 1000, 'free_bytes': 500, 'allocator_peak_bytes': 100, 'kind': 'DEDICATED'}, 'kernels_completed': True, 'resident_block_hash': 'b1'}
        receipt = {'timestamp': now.isoformat(), 'artifacts': [{'sha256': 'a'*64}], 'devices': [dev], 'claims': []}
        res = qv.validate_result(receipt, now_utc=now, trusted_artifact_hashes=frozenset(['a'*64]))
        self.assertNotIn('MALFORMED_PCI:0000:01:00.0', res['reasons'])

